//! komga service backend — Comics/manga server.
//!
//! Implements `ServiceBackend` so the generic `service.*` tools
//! (deploy/backup/restore/configure/status/connect/sync) drive komga,
//! alongside the `komga.` library audit/renumber/dedupe/scan and readlist tools in
//! [`tools`]. The only orca dep is `plugin-toolkit`. See
//! orca/docs/PLUGIN-PROGRAM.md.
#![allow(clippy::disallowed_types)]

pub mod api;
pub mod audit;
pub mod execute;
pub mod operations;
pub mod parse;
pub mod readlist;
pub mod tools;

/// Typed Komga client generated by `progenitor` from
/// `specs/komga.openapi.json` at build time.
pub mod komga_api {
    #[allow(
        clippy::all,
        dead_code,
        unused_imports,
        unused_variables,
        non_snake_case
    )]
    mod generated {
        include!(concat!(env!("OUT_DIR"), "/komga_codegen.rs"));
    }

    pub use generated::{types, ByteStream, Error, ResponseValue};

    /// The generated client, constructible only with the API key on orca's
    /// delegated `http.request` transport; its methods are reached via `Deref`.
    pub struct Client(generated::Client);

    impl Client {
        pub fn new(
            base_url: &str,
            api_key: &str,
            insecure: bool,
        ) -> plugin_toolkit::prelude::Result<Self> {
            let http = plugin_toolkit::api_client::ApiClientBuilder::new()
                .header("X-API-Key", api_key)?
                .insecure(insecure)
                .build()?;
            Ok(Self(generated::Client::new_with_client(
                base_url.trim_end_matches('/'),
                http,
            )))
        }
    }

    impl std::ops::Deref for Client {
        type Target = generated::Client;
        fn deref(&self) -> &generated::Client {
            &self.0
        }
    }
}

use plugin_toolkit::service::{
    BoxFuture, Routes, Runtime, ServiceBackend, ServiceError, ServiceStatus, WorkloadSpec,
};

/// komga backend. Holds only the provider name; per-instance routes/creds
/// come from the `Routes` the generic `service.*` tools hand each op.
#[derive(Debug, Clone)]
pub struct KomgaBackend {
    provider: &'static str,
}

impl KomgaBackend {
    pub fn new(provider: &'static str) -> Self {
        Self { provider }
    }
}

impl ServiceBackend for KomgaBackend {
    fn provider(&self) -> &str {
        self.provider
    }

    /// Runtimes komga can be placed on. `service.deploy` hands the
    /// `workload_spec` below to a matching deploy target — this backend never
    /// drives pct/docker itself (that mechanic lives in the deploy-target domain).
    fn runtimes(&self) -> Vec<Runtime> {
        vec![Runtime::Docker, Runtime::Podman, Runtime::Lxc, Runtime::Vm]
    }

    fn default_port(&self) -> u16 {
        25600
    }

    /// In-workload paths holding config/data. This is ALL komga declares for
    /// backup — the generic pluggable backup (tar for containers/LXC, PBS for
    /// Proxmox guests when available) snapshots these. No backup/restore code
    /// here; those are inherited from ServiceBackend's defaults.
    fn data_paths(&self) -> Vec<String> {
        vec!["/config".to_string()]
    }

    fn workload_spec<'a>(
        &'a self,
        _runtime: Runtime,
        _instance: &'a str,
        _routes: &'a Routes,
    ) -> BoxFuture<'a, Result<WorkloadSpec, ServiceError>> {
        // TODO: describe the komga workload (image/template, ports, mounts,
        // env) for the chosen runtime. The deploy target turns this into a
        // compose service / LXC config / VM. See deploy-target::WorkloadSpec.
        Box::pin(async move { Err(ServiceError::unimplemented("komga.workload_spec")) })
    }

    fn configure<'a>(
        &'a self,
        _instance: &'a str,
        _routes: &'a Routes,
        _config: &'a str,
    ) -> BoxFuture<'a, Result<(), ServiceError>> {
        // TODO: apply komga-specific config idempotently.
        Box::pin(async move { Err(ServiceError::unimplemented("komga.configure")) })
    }

    fn status<'a>(
        &'a self,
        _instance: &'a str,
        _routes: &'a Routes,
    ) -> BoxFuture<'a, Result<ServiceStatus, ServiceError>> {
        // TODO: real health/diagnostics.
        Box::pin(async move { Err(ServiceError::unimplemented("komga.status")) })
    }
}

